      "support_status": "SUFFICIENT",
      "rationale": "P027 explicitly states this limit and identifies the assumption-dependent methods to which it applies."
    }
  },
  "signal_basis": {
    "component_id": "C048.signal_basis",
    "value": "A smaller configuration repeatedly reproduces lateness while specified further removals do not; reconstructed on-time bookings are compared to check for omitted operating conditions.",
    "scope": "Results within the selected reconstruction or replay, with equipment, agreed deadline and other test conditions fixed.",
    "provenance": {
      "refs": [
